import React, { useState } from 'react';
import { CalendarEvent, Category, WeekDay } from '../types';

interface AddEventModalProps {
  isOpen: boolean;
  defaultDay: WeekDay;
  onClose: () => void;
  onAdd: (event: CalendarEvent) => void;
}

const CATEGORIES: Category[] = ['Meeting', 'Deadline', 'Focus block', 'Personal'];
const DAYS: WeekDay[] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

export const AddEventModal: React.FC<AddEventModalProps> = ({
  isOpen,
  defaultDay,
  onClose,
  onAdd
}) => {
  const [title, setTitle] = useState('');
  const [time, setTime] = useState('10:00');
  const [day, setDay] = useState<WeekDay>(defaultDay);
  const [category, setCategory] = useState<Category>('Meeting');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;

    onAdd({
      id: 'custom-' + Date.now().toString(),
      title,
      time,
      day,
      category
    });

    setTitle('');
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
      <div 
        style={{ backgroundColor: '#0b1329', borderColor: '#1e293b' }} 
        className="w-full max-w-md border rounded-xl p-5 shadow-2xl text-left"
      >
        <h3 className="text-sm font-bold text-white mb-4">Schedule Custom Event</h3>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-medium text-slate-300 mb-1">Event Title</label>
            <input
              type="text"
              required
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="E.g., Architecture Sync"
              className="w-full px-3 py-2 text-xs rounded bg-[#131b2e] border border-slate-700 text-white focus:outline-none focus:border-blue-500"
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-slate-300 mb-1">Day of Week</label>
              <select
                value={day}
                onChange={(e) => setDay(e.target.value as WeekDay)}
                className="w-full px-3 py-2 text-xs rounded bg-[#131b2e] border border-slate-700 text-white focus:outline-none focus:border-blue-500"
              >
                {DAYS.map((d) => (
                  <option key={d} value={d}>{d}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-300 mb-1">Time (HH:MM)</label>
              <input
                type="text"
                required
                value={time}
                onChange={(e) => setTime(e.target.value)}
                placeholder="14:00"
                className="w-full px-3 py-2 text-xs rounded bg-[#131b2e] border border-slate-700 text-white focus:outline-none focus:border-blue-500"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-slate-300 mb-1">Category</label>
            <select
              value={category}
              onChange={(e) => setCategory(e.target.value as Category)}
              className="w-full px-3 py-2 text-xs rounded bg-[#131b2e] border border-slate-700 text-white focus:outline-none focus:border-blue-500"
            >
              {CATEGORIES.map((c) => (
                <option key={c} value={c}>{c}</option>
              ))}
            </select>
          </div>

          <div className="flex justify-end space-x-2 pt-3 border-t border-slate-800">
            <button
              type="button"
              onClick={onClose}
              className="px-3.5 py-1.5 rounded text-xs text-slate-300 hover:bg-slate-800"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-1.5 rounded text-xs font-semibold bg-blue-600 hover:bg-blue-500 text-white shadow"
            >
              Add Event
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};
